}
const B = 20, batches = Math.ceil(hashes.length / B);
let next = 0, nhops = 0, failed = 0;
const w = fs.createWriteStream(hopFile, { flags: 'a' }), d = fs.createWriteStream(doneFile, { flags: 'a' });
await Promise.all(Array.from({ length: 4 }, async () => {
  while (next < batches) {
